using UnityEngine;

/// <summary>
/// Скрипт, обеспечивающий плавное вращение объекта вокруг оси Y со скоростью 30 градусов в секунду.
/// </summary>
public class YAxisRotator : MonoBehaviour
{
    // Скорость вращения в градусах в секунду
    [SerializeField]
    private float rotationSpeed = 30f;

    private void Update()
    {
        // Плавное вращение вокруг оси Y
        transform.Rotate(0f, rotationSpeed * Time.deltaTime, 0f, Space.Self);
    }
}

